using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.PurchaseInvoices.Dtos;using Namaa.Domain.Common.Results;namespace Namaa.Application.PurchaseInvoices.Queries.GetPurchaseInvoices;public sealed class GetPurchaseInvoicesQueryHandler(IPurchaseInvoiceRepository repository):IRequestHandler<GetPurchaseInvoicesQuery,Result<IReadOnlyList<PurchaseInvoiceDto>>>{public async Task<Result<IReadOnlyList<PurchaseInvoiceDto>>>Handle(GetPurchaseInvoicesQuery request,CancellationToken cancellationToken)=>Result.Success<IReadOnlyList<PurchaseInvoiceDto>>((await repository.GetAllAsync(cancellationToken)).Select(PurchaseInvoiceDto.FromEntity).ToList());}
